function capitalize(text) {
  return text ? text[0].toUpperCase() + text.slice(1) : text;
}

function slugify(text) {
  throw new Error('not implemented');
}

module.exports = { capitalize, slugify };

const assert = require('assert');
const { capitalize } = require('../src/strings');

test('capitalize first letter', () => assert.strictEqual(capitalize('hello'), 'Hello'));
test('capitalize empty string', () => assert.strictEqual(capitalize(''), ''));

input.command:
cat >> test/strings.test.js <<'EOF'

test('slugify lowercases and hyphenates', () => assert.strictEqual(slugify('Hello World'), 'hello-world'));
test('slugify removes diacritics', () => assert.strictEqual(slugify('Café Crème'), 'cafe-creme'));
test('slugify handles Vietnamese and đ/Đ', () => {
  assert.strictEqual(slugify('Đường Nguyễn Huệ'), 'duong-nguyen-hue');
  assert.strictEqual(slugify('đĐ'), 'dd');
});
test('slugify collapses runs of symbols', () => assert.strictEqual(slugify('a  &&  b__c'), 'a-b-c'));
test('slugify trims leading and trailing hyphens', () => assert.strictEqual(slugify('  --Hi!--  '), 'hi'));
test('slugify keeps digits', () => assert.strictEqual(slugify('Top 10 of 2024'), 'top-10-of-2024'));
test('slugify empty and symbol-only input', () => {
  assert.strictEqual(slugify(''), '');
  assert.strictEqual(slugify('!!!'), '');
});
test('slugify truncates to 50 chars', () => assert.strictEqual(slugify('a'.repeat(80)), 'a'.repeat(50)));
test('slugify truncated slug does not end with hyphen', () => {
  const s = slugify('a'.repeat(49) + ' bbb');
  assert.strictEqual(s, 'a'.repeat(49));
});
test('slugify keeps 50 chars when cut lands on a letter', () => {
  const s = slugify('a'.repeat(49) + '-bbb');
  assert.ok(s.length <= 50 && !s.endsWith('-'));
});
EOF
